"""Reattach Lima's boot metadata after RAM restore, without rebooting the guest."""
from pathlib import Path
import subprocess

point = '/mnt/lima-cidata'
device = subprocess.check_output(['findmnt', '-n', '-o', 'SOURCE', point], text=True).strip()
# cidata.iso is regenerated by Lima outside the snapshot. Its old filesystem
# pages can still be cached in saved RAM, even though QEMU opened the new ISO.
subprocess.check_call(['umount', point])
subprocess.check_call(['blockdev', '--flushbufs', device])
subprocess.check_call(['mount', '-o', 'ro', device, point])
value = next(line.split(':', 1)[1].strip() for line in Path(point + '/meta-data').read_text().splitlines()
             if line.startswith('instance-id:'))
for name in ('lima-ssh-ready', 'lima-boot-done'):
    Path('/run/' + name).write_text(value + '\n')
